    var W = 0, H = 0, SIDE = 0;
    var basketX = 0, targetX = 0, dragging = false;
    var drops = [], score = 0, lastSpawn = 0, t0 = performance.now();
    var raf = 0;

    function sizeCanvas() {
      if (g.OMNI_LAYOUT) { var m = g.OMNI_LAYOUT.get(); W = m.w; H = m.h; }
      else { var r = cv.getBoundingClientRect(); W = r.width; H = r.height; }
